<script setup lang="ts">
import { vMotionPanel } from '../../directives/siteMotion'
import { computed, ref } from 'vue'
import { ABILITY_KEYS, SKILL_ABILITY } from '../../lib/calc'
import { contentLabel, type SrdRef } from '../../lib/srd'
import { newWorkshopFeature, newWorkshopResource, workshopProblems, type WorkshopDraft, type WorkshopStep } from '../../lib/homebrew-workshop'
const props=defineProps<{personalEdition?:boolean;draft:WorkshopDraft;step:WorkshopStep;spells:(SrdRef&{level?:number})[]}>()
const emit=defineEmits<{step:[value:WorkshopStep];save:[];publish:[]}>()
const race=computed(()=>props.draft.race!)
const query=ref(''),selected=ref('')
const spellOptions=computed(()=>props.spells.filter(s=>`${s.name} ${s.sourcePack??''}`.toLowerCase().includes(query.value.toLowerCase())).slice(0,60))
const words=(value:string)=>[...new Set(value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean))]
const problems=computed(()=>workshopProblems(props.draft))
function toggle(list:string[],value:string){const i=list.indexOf(value);if(i<0)list.push(value);else list.splice(i,1)}
function addSpell(){const spell=props.spells.find(s=>s.index===selected.value);if(!spell||race.value.spells.some(s=>s.index===spell.index))return;race.value.spells.push({id:crypto.randomUUID(),index:spell.index,name:spell.name,level:1,ability:'cha',usage:'',needsReview:true});selected.value=''}
</script>

<template><section v-motion-panel="step" class="hw-editor hw-panel"><header class="hw-editor-header"><p class="hw-eyebrow">RACE BUILDER</p><h2>{{({identity:'Identity',foundation:'Body & training',progression:'Trait progression',magic:'Innate spells',resources:'Resource trackers',features:'Traits & choices',review:'Review'})[step]}}</h2><p class="hw-hint">Saved racial rules apply to every matching character. Ability scores and play state are preserved.</p></header>
  <div v-if="step==='identity'" class="hw-section-body">
    <div class="hw-form-grid"><label>Race name<input v-model="draft.name" maxlength="200" placeholder="Shadow Touched" /></label><label>Source / collection<input v-model="draft.source" maxlength="200" /></label></div>
    <label>Description & lore<textarea v-model="draft.description" rows="8" /></label>
    <aside v-if="draft.imported" class="hw-callout"><strong>Editing imported content</strong><p>{{draft.imported.sources.join(' · ')||draft.source}}</p><p>You can save into the original file, another pack, or a new pack. Original fields outside this editor remain preserved.</p></aside>
  </div>
  <div v-else-if="step==='foundation'" class="hw-section-body">
    <div class="hw-form-grid"><label>Walking speed (feet)<input v-model.number="race.speed" type="number" min="0" max="1000" /></label><label>Size<select v-model="race.size"><option v-for="size in ['tiny','small','medium','large','huge','gargantuan']" :key="size">{{size}}</option></select></label><label>Darkvision (feet; 0 for none)<input v-model.number="race.darkvision" type="number" min="0" max="1000" /></label></div>
    <h3>Ability bonuses</h3><p class="hw-hint">New characters receive these through character creation. Existing scores are kept; changed bonuses are flagged for review.</p>
    <div class="hw-form-grid"><label v-for="ability in ABILITY_KEYS" :key="ability">{{ability.toUpperCase()}} bonus<input v-model.number="race.abilityBonuses[ability]" type="number" min="-10" max="10" /></label></div>
    <div class="hw-form-grid"><label>Languages · one per line<textarea :value="race.languages.join('\n')" rows="3" @change="race.languages=words(($event.target as HTMLTextAreaElement).value)" /></label><label>Tool proficiencies<textarea :value="draft.tools.join('\n')" rows="3" @change="draft.tools=words(($event.target as HTMLTextAreaElement).value)" /></label><label>Armour proficiencies<textarea :value="draft.armor.join('\n')" rows="3" @change="draft.armor=words(($event.target as HTMLTextAreaElement).value)" /></label><label>Weapon proficiencies<textarea :value="draft.weapons.join('\n')" rows="3" @change="draft.weapons=words(($event.target as HTMLTextAreaElement).value)" /></label></div>
    <fieldset class="hw-check-group"><legend>Granted skill proficiencies</legend><label v-for="(_,skill) in SKILL_ABILITY" :key="skill"><input type="checkbox" :checked="race.skills.includes(String(skill))" @change="toggle(race.skills,String(skill))" />{{String(skill).replace(/([A-Z])/g,' $1')}}</label></fieldset>
    <div class="hw-form-grid"><label>Damage resistances · one per line<textarea :value="race.resistances.join('\n')" rows="3" @change="race.resistances=words(($event.target as HTMLTextAreaElement).value)" /></label><label>Damage immunities · one per line<textarea :value="race.immunities.join('\n')" rows="3" @change="race.immunities=words(($event.target as HTMLTextAreaElement).value)" /></label></div>
    <label>Natural armour rules<textarea v-model="race.naturalArmor" rows="3" placeholder="Formula and conditions, if applicable" /></label><p class="hw-hint">Armour rules are displayed as racial features. Review the character’s AC mode and value separately.</p>
  </div>
  <div v-else-if="step==='progression'" class="hw-section-body"><p class="hw-callout">Racial traits and resource trackers unlock at character level, including for multiclass characters.</p><div v-for="feature in [...draft.features].sort((a,b)=>a.level-b.level)" :key="feature.id" class="hw-rule-card"><div class="hw-between"><strong>{{feature.name||'Unnamed trait'}}</strong><span>Level {{feature.level}}</span></div></div><button class="hw-button" @click="emit('step','features')">Edit traits & gained levels</button></div>
  <div v-else-if="step==='magic'" class="hw-section-body">
    <p class="hw-callout">Innate spells are separate from class spells. They do not consume class spell allowances or replace class slots. Add a resource tracker for any limited free casts.</p>
    <label>Find a spell<input v-model="query" type="search" placeholder="Spell name or source…" /></label><label>Spell definition<select v-model="selected"><option value="">Choose a spell…</option><option v-for="spell in spellOptions" :key="spell.index" :value="spell.index">{{contentLabel(spell)}} · {{spell.sourcePack||'SRD 2014'}}</option></select></label><button class="hw-button" :disabled="!selected" @click="addSpell">+ Innate spell</button>
    <article v-for="(spell,i) in race.spells" :key="spell.id" class="hw-rule-card"><div class="hw-between"><h3>{{spell.name}}</h3><button class="hw-text-button" @click="race.spells.splice(i,1)">Remove</button></div><div class="hw-form-grid"><label>Character unlock level<input v-model.number="spell.level" type="number" min="1" max="20" /></label><label>Casting ability<select v-model="spell.ability"><option v-for="ability in ABILITY_KEYS" :key="ability" :value="ability">{{ability.toUpperCase()}}</option></select></label></div><label>Casting limits & recovery<textarea v-model="spell.usage" rows="3" placeholder="At will; once per long rest; may also use spell slots…" /></label><label class="hw-check"><input v-model="spell.needsReview" type="checkbox" /> Casting rules still need DM review</label><label>Spell definition<select v-model="spell.index" @change="spell.name=spells.find(s=>s.index===spell.index)?.name??spell.name"><option v-if="!spells.some(s=>s.index===spell.index)" :value="spell.index">{{spell.name}} · original reference</option><option v-for="entry in spellOptions" :key="entry.index" :value="entry.index">{{contentLabel(entry)}} · {{entry.sourcePack||'SRD 2014'}}</option></select></label></article>
  </div>
  <div v-else-if="step==='resources'" class="hw-section-body"><button class="hw-button" @click="draft.resources.push(newWorkshopResource())">+ Resource tracker</button><p class="hw-hint">Scale points, dice, or limited uses with character level, an ability modifier, or proficiency.</p><article v-for="(r,i) in draft.resources" :key="r.id" class="hw-rule-card"><div class="hw-between"><h3>{{r.name||'New tracker'}}</h3><button class="hw-text-button" @click="draft.resources.splice(i,1)">Remove</button></div><div class="hw-form-grid"><label>Name<input v-model="r.name" /></label><label>Character unlock level<input v-model.number="r.level" type="number" min="1" max="20" /></label><label>Maximum from<select v-model="r.basis"><option value="fixed">Fixed amount</option><option value="level">Character level</option><option value="ability">Ability modifier</option><option value="proficiency">Proficiency bonus</option></select></label><label v-if="r.basis==='ability'">Ability<select v-model="r.ability"><option v-for="ability in ABILITY_KEYS" :key="ability" :value="ability">{{ability.toUpperCase()}}</option></select></label><label v-if="r.basis!=='fixed'">Multiplier<input v-model.number="r.multiplier" type="number" min="0" max="99" /></label><label>{{r.basis==='fixed'?'Maximum':'Add base amount'}}<input v-model.number="r.base" type="number" min="0" max="999" /></label><label>Minimum<input v-model.number="r.minimum" type="number" min="0" max="999" /></label><label>Recovery<select v-model="r.recovery"><option value="long">Long rest</option><option value="short">Short rest</option><option value="manual">Manual</option></select></label><label>Unlimited from character level<input :value="r.unlimitedAt" type="number" min="1" max="20" placeholder="Never" @input="r.unlimitedAt=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null" /></label></div><label>Usage notes<textarea v-model="r.notes" rows="3" /></label></article></div>
  <div v-else-if="step==='features'" class="hw-section-body"><p v-if="personalEdition" class="hw-hint">Save this personal edition below, then review and apply changes to each existing character.</p><div class="hw-actions"><button class="hw-button" @click="draft.features.push(newWorkshopFeature())">+ Trait</button><button class="hw-button" @click="draft.features.push(newWorkshopFeature(true))">+ Choice</button></div><p class="hw-hint">These are the racial traits shown on every linked sheet. Body, training, and innate spell grants are displayed separately in the preview.</p><details v-for="(feature,i) in draft.features" :key="feature.id" class="hw-feature-editor" :open="!feature.name"><summary>{{feature.name||'New trait'}} · Level {{feature.level}}</summary><div class="hw-feature-fields"><label>Name<input v-model="feature.name" /></label><label>Gained at character level<input v-model.number="feature.level" type="number" min="1" max="20" /></label><label>Rules & description<textarea v-model="feature.description" rows="6" /></label><template v-if="feature.choice"><label>Choose how many<input v-model.number="feature.choose" type="number" min="1" max="99" /></label><label>Options · one per line<textarea :value="feature.options.join('\n')" rows="4" @change="feature.options=words(($event.target as HTMLTextAreaElement).value)" /></label></template><button class="hw-text-button" @click="draft.features.splice(i,1)">Remove trait</button></div></details></div>
  <div v-else class="hw-section-body"><h3>{{draft.name||'Unnamed race'}}</h3><p>{{draft.features.length}} traits · {{race.spells.length}} innate spells · {{draft.resources.length}} trackers</p><ul v-if="problems.length" class="hw-alert"><li v-for="problem in problems" :key="problem">{{problem}}</li></ul><aside v-if="!personalEdition" class="hw-callout"><strong>Update all characters using this race</strong><p>Traits, racial grants, and resource maximums update when saved. Existing scores, HP, equipment, spent uses, and player choices are preserved. Ability bonus changes and conflicting character edits are flagged for review.</p></aside><div class="hw-actions"><button class="hw-button" v-if="!personalEdition" @click="emit('save')">{{personalEdition?'Review entry changes':'Save draft on this device'}}</button><button class="hw-button hw-button-primary" :disabled="!!problems.length" v-if="!personalEdition" @click="emit('publish')">{{personalEdition?'Review entry changes':'Save to pack & update characters'}}</button></div></div>
</section></template>
